## Kotlin/Spring 잠금 구현

### 비관적 잠금 (Pessimistic Locking)

```kotlin
@Entity
@Table(name = "products")
class Product(
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    val id: Long = 0,
    var name: String,
    var stock: Int,
    var price: BigDecimal
) {
    fun decreaseStock(quantity: Int) {
        require(stock >= quantity) { "재고 부족: 현재=$stock, 요청=$quantity" }
        stock -= quantity
    }
}

interface ProductRepository : JpaRepository<Product, Long> {

    // PESSIMISTIC_WRITE → SELECT ... FOR UPDATE
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("SELECT p FROM Product p WHERE p.id = :id")
    fun findByIdForUpdate(id: Long): Product?

    // PESSIMISTIC_WRITE + NOWAIT 힌트
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @QueryHints(QueryHint(name = "jakarta.persistence.lock.timeout", value = "0"))
    @Query("SELECT p FROM Product p WHERE p.id = :id")
    fun findByIdForUpdateNowait(id: Long): Product?
}

@Service
class StockService(private val productRepository: ProductRepository) {

    @Transactional
    fun decreaseStock(productId: Long, quantity: Int) {
        val product = productRepository.findByIdForUpdate(productId)
            ?: throw ProductNotFoundException(productId)
        product.decreaseStock(quantity)
        // 트랜잭션 커밋 시 잠금 자동 해제
    }
}
```

### 낙관적 잠금 (Optimistic Locking)

```kotlin
@Entity
@Table(name = "products")
class Product(
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    val id: Long = 0,
    var name: String,
    var stock: Int,

    @Version
    var version: Long = 0  // JPA가 자동으로 관리
)

// 실행되는 SQL:
// UPDATE products SET stock = ?, version = version + 1
// WHERE id = ? AND version = ?
// → 영향받은 행이 0이면 OptimisticLockException 발생
```

